    "notes": [
      {
        "line": 1,
        "title": "Adivinanza: la criatura sin nombre",
        "body": "El poema no dice «snake» en ningún momento. Los detalles de las seis estrofas permiten inferir que se trata de una serpiente, pero la identificación forma parte del recorrido de lectura. El título «The Snake» fue añadido por los editores de su publicación en 1866, destruyendo ese efecto inicial."
      },
      {
        "line": 2,
        "title": "Rides",
        "body": "El verbo «rides» humaniza a la criatura al sugerir que monta o cabalga, aunque se describe un avance sobre la hierba. La traducción conserva la extrañeza en lugar de normalizarlo como «se arrastra»."
      },
      {
        "line": 3,
        "title": "El verso que Dickinson defendió",
        "body": "En la publicación de 1866 se añadió puntuación al final de la tercera línea, separándola de la cuarta. Dickinson se quejó ante Higginson de que, para ella, ambas formaban una unidad. Nuestra versión procura leer «did you not / His notice sudden is» como «si no lo conociste, su presencia se anuncia de improviso»."
      },
      {
        "line": 5,
        "title": "Una marca que se borra",
        "body": "El peine abre una raya y la hierba vuelve a cerrarse: se percibe al animal por el efecto fugaz que produce en el terreno. La imagen depende tanto del ocultamiento como de lo visible."
      },
      {
        "line": 6,
        "title": "Spotted shaft",
        "body": "«Shaft» puede significar vara o tallo; «spotted» sugiere manchas en la superficie. El poema registra algo que aparece a trozos antes de proporcionar al lector suficiente información para reconocerlo."
      },
      {
        "line": 9,
        "title": "Boggy Acre / Corn",
        "body": "Los campos cenagosos y suelos demasiado frescos para el maíz sitúan al animal en un hábitat concreto. El contraste con el cultivo humano reitera que la naturaleza no está siempre ordenada para nuestras necesidades."
      },
      {
        "line": 11,
        "title": "La voz «cuando era Niño»",
        "body": "El texto adopta «when a Boy», y por eso la traducción mantiene «Niño». No obliga a identificar la voz del poema literalmente con la biografía o el género de Dickinson: la hablante poética puede representar una experiencia o una máscara."
      },
      {
        "line": 13,
        "title": "Whip lash",
        "body": "La apariencia de una correa de látigo que se destrenza al sol prolonga la adivinanza y el movimiento del animal. Al intentar tomar el objeto, la voz descubre que estaba vivo."
      },
      {
        "line": 17,
        "title": "Nature's People",
        "body": "La naturaleza aparece como una comunidad de personas. Sin embargo, las estrofas finales ponen un límite a esa cordialidad: familiaridad no equivale a confianza universal."
      },
      {
        "line": 24,
        "title": "Zero at the Bone",
        "body": "Una cifra abstracta, «Zero», nombra una sensación física extrema: un frío que atraviesa el cuerpo hasta los huesos. Puede sugerir tanto el miedo súbito como una experiencia radical de alteridad."
      },
      {
        "line": 1,
        "title": "Historia de publicación",
        "body": "El Springfield Daily Republican publicó el poema el 14 de febrero de 1866 como «The Snake», con alteraciones editoriales; Dickinson escribió a Thomas Wentworth Higginson el 17 de marzo de 1866 para protestar, especialmente por la puntuación. Véase Miller, nota a la hoja 54, y Emily Dickinson Museum, «Poems Published in Dickinson's Lifetime»."
      }
    ]
